import {
  segmentCacheMap,
  type SegmentCacheEntry,
  type RouteTree,
  type RootRouteTree,
  type RSCSegmentData,
  type RefreshState,
  type FulfilledRouteCacheEntry,
  rebaseInactiveRouteTree,
